result:
.signIn{
	width: 100%;
	padding: 12px;
	background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);

	.signInBg{
		width: 100%;
		height: 70px;
		border-radius: 8px;
		background: linear-gradient(90deg, #FFE8F5 0%, #F1FBFD 100%);
		padding: 0 3px;
		.item{
			text-align: center;
			font-size: 11px;
			color: #999999;
			padding-top: 5px;
			&.gift{
				padding-bottom: 3px;
				img {
					width: 32px;
					height: 32px;
					margin-bottom: 2px;
				}
			}
			img {
				width: 24px;
				height: 24px;
				display: block;
				margin-bottom: 6px;
			}
		}
		.bnt{
			width: 44px;
			height: 24px;
			background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
			border-radius: 12px;
			text-align: center;
			line-height: 24px;
			font-size: 12px;
			color: #fff;
		}
		&.on{
			background: #fff;
			padding: 0 10px;
			.bnt{
				width: 70px;
				height: 26px;
				background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
				border-radius: 13px;
				font-size: 12px;
				color: #FFFFFF;
				text-align: center;
				line-height: 26px;
			}
			.pictrue{
				width: 44px;
				height: 44px;
				margin-right: 10px;
				img {
					width: 100%;
					height: 100%;
				}
			}
			.name{
				color: #282828;
				font-size: 15px;
				font-weight: 600;
				line-height: 1;
			}
			.points{
				width: 40px;
				height: 16px;
				background: #FCEAE9;
				border-radius: 12px;
				font-size: 10px;
				color: #E93323;
				margin-left: 2px;

				.pointsBg{
					width: 100%;
					height: 100%;
				}

				img {
					width: 14px;
					height: 14px;
					display: block;
				}
			}
			.tips{
				color: #999999;
				font-size: 12px;
				margin-top: 6px;
			}
		}
	}
}
